package com.commutemate.ride;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="rides") public class ConfirmedRide { @Id @GeneratedValue private UUID id; @Column(name="tenant_id",nullable=false) private UUID tenantId; @Column(name="ride_offer_id",nullable=false) private UUID rideOfferId; @Column(name="driver_user_id",nullable=false) private UUID driverUserId; @Column(name="rider_user_id",nullable=false) private UUID riderUserId; @Column(name="location_id",nullable=false) private UUID locationId; @Column(name="departure_at",nullable=false) private Instant departureAt; @Column(nullable=false) private String status="CONFIRMED"; @Column(name="confirmed_at",nullable=false) private Instant confirmedAt=Instant.now(); protected ConfirmedRide(){} public ConfirmedRide(RideOffer o,UUID rider){tenantId=o.getTenantId();rideOfferId=o.getId();driverUserId=o.getDriverUserId();riderUserId=rider;locationId=o.getLocationId();departureAt=o.getDepartureAt();} public UUID getId(){return id;} public UUID getTenantId(){return tenantId;} public UUID getDriverUserId(){return driverUserId;} public UUID getRiderUserId(){return riderUserId;} public UUID getLocationId(){return locationId;} public Instant getDepartureAt(){return departureAt;} public String getStatus(){return status;} }
